"""New-directory-only addendum freeze, no existing file writes."""
import pathlib,json,hashlib
out=pathlib.Path(__file__).resolve().parent;repo=out.parent.parents[4];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();rel=lambda p:str(p.relative_to(repo));write=lambda p,x:p.write_text(json.dumps(x,indent=2)+'\n')
controls=json.loads((out/'actual-pure-addendum-controls.json').read_text());assert controls['result']=='passed' and len(controls['records'])==31
inputs=controls['inputIdentities'];assert all(sha(repo/p)==h for p,h in inputs.items())
manifest=out/'artifact-manifest.json';receipt=out/'stable-addendum-receipt.json';verification=out/'manifest-verification.json';excluded={manifest,receipt,verification,out/'freeze.stdout',out/'freeze.stderr'}
files=[{'path':rel(p),'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(out.rglob('*')) if p.is_file() and p not in excluded]
write(manifest,{'scope':'new field-count addendum files only; frozen old inputs referenced unchanged, no root integration','files':files,'excluded':[rel(p) for p in sorted(excluded)]})
write(receipt,{'scope':'stable additive DCTRL-RECHECK-DOC01 count correction; NOT ACCEPTED; no root integration or native execution','baseline':'6606af9e590032f328f330ecb3d953b1eef027e3','parentFrozenControllerReceipt':{'path':'docs/review/evidence/config-acceptance/delivery/delivery-stable-controller-material-corrections-6606-20261013.json','sha256':inputs['docs/review/evidence/config-acceptance/delivery/delivery-stable-controller-material-corrections-6606-20261013.json']},'supersession':{'path':rel(out/'field-count-supersession.json'),'sha256':sha(out/'field-count-supersession.json'),'oldPointer':'#/cases/3/oracle','oldCount':27,'authoritativeCount':24,'preservedMemberObligations':24,'originalBody':'retained byte-exact in frozen old file and quoted unchanged in additive supersession'},'actualPureControls':{'path':rel(out/'actual-pure-addendum-controls.json'),'sha256':sha(out/'actual-pure-addendum-controls.json'),'count':31,'result':'passed','scope':'source/member/JSON/hash/scope conservation only; not native/Go/API/auth/host/runtime proof'},'frozenInputsUnchanged':inputs,'artifactManifest':{'path':rel(manifest),'sha256':sha(manifest),'files':len(files)},'nativeResults':'12controller correction subcases and204canonical future cases remain NOTRUN; none modified','writes':'new controller-ready-v2-field-count-addendum-6606 directory only','pause':'all existing Delivery/root-review inputs remain strictly unchanged until explicit parent resume','acceptance':'NOT ACCEPTED; no row/native/root/global promotion'})
errors=[x['path'] for x in files if sha(repo/x['path'])!=x['sha256']];assert not errors
write(verification,{'scope':'actual new-directory SHA verification and frozen15input hashes remain unchanged','manifestSha256':sha(manifest),'receiptSha256':sha(receipt),'fileCount':len(files),'errors':errors,'result':'passed'})
print(json.dumps({'receipt':rel(receipt),'receiptSha256':sha(receipt),'manifestSha256':sha(manifest),'verificationSha256':sha(verification),'files':len(files),'pureControls':31,'authoritativeMembers':24,'state':'FROZEN ADDITIVE ONLY, NOT ACCEPTED'},indent=2))
